<?php
session_start();if(!isset($_SESSION['user_id'])){header('Location: login.html');exit;}
require __DIR__.'/db.php';require __DIR__.'/artwork-common.php';$uid=(int)$_SESSION['user_id'];if(!artworkIsStudent($conn,$uid)){http_response_code(403);exit('Student access only.');}
$stmt=$conn->prepare('SELECT a.artwork_id,a.title,a.status,a.rejection_reason,a.created_at,c.category_name,(SELECT image_path FROM artwork_images WHERE artwork_id=a.artwork_id ORDER BY image_id LIMIT 1) AS image_path FROM artworks a JOIN categories c ON c.category_id=a.category_id WHERE a.user_id=? ORDER BY a.created_at DESC,a.artwork_id DESC');$stmt->bind_param('i',$uid);$stmt->execute();$rows=$stmt->get_result();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Artworks | MIRA</title><link rel="stylesheet" href="artwork-workflow.css"><script src="theme.js" defer></script></head><body class="mira-workflow"><main class="workflow-wrap"><header class="workflow-top"><a class="back-link" href="user-home.php">← Back to gallery</a><button type="button" class="theme-toggle">🌙</button></header><div class="workflow-heading"><p class="overline">MY MIRA STUDIO</p><h1>Submission history</h1><p>Track your artwork as the MIRA team reviews each submission.</p></div><p><a class="primary-btn" href="upload-artwork.php">+ New artwork</a></p><section class="art-list">
<?php if(!$rows->num_rows): ?><div class="form-card">No submissions yet. Share your first artwork!</div><?php endif; ?>
<?php while($a=$rows->fetch_assoc()):$status=strtolower($a['status']); ?><article class="art-row"><div class="art-thumb"><?php if($a['image_path']): ?><img src="<?= artworkEscape($a['image_path']) ?>" alt="<?= artworkEscape($a['title']) ?>"><?php else: ?><span>✦</span><?php endif; ?></div><div class="art-meta"><h2><?= artworkEscape($a['title']) ?></h2><p><?= artworkEscape($a['category_name']) ?> · <?= artworkEscape(date('M j, Y',strtotime($a['created_at']))) ?></p><?php if($status==='rejected' && $a['rejection_reason']): ?><p class="rejection">Reason: <?= artworkEscape($a['rejection_reason']) ?></p><?php endif; ?></div><span class="state state-<?= in_array($status,['pending','approved','rejected'],true)?$status:'pending' ?>"><?= artworkEscape(ucfirst($status)) ?></span></article><?php endwhile; ?>
</section></main></body></html>
